"""Derive non-sensitive training-telemetry attributes for a Mantle agent.

Builds the ``Training Started`` payload sent by
:func:`rasa.telemetry.track_mantle_model_training`. Only derived aggregates are
collected — counts, kind/type distributions, booleans, and provider/model/
vector-store/channel enums — never raw artifacts (prompts, skill/flow bodies,
persona, rules, knowledge content) or author-chosen identifiers (skill/flow/tool/
field names, knowledge-store ids, MCP urls). Every collector is best-effort: a
failure in one section is logged and skipped so telemetry never breaks training.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Callable, Mapping, Optional

import structlog

from rasa.mantle.config.agent_spec import AgentSpec, agent_spec_from_config
from rasa.mantle.content.responses import RESPONSES_FILENAME, ResponseRegistry
from rasa.mantle.memory.field import (
    MEMORY_FIELD_TYPE_ANY,
    MEMORY_FIELD_TYPE_BOOL,
    MEMORY_FIELD_TYPE_CATEGORICAL,
    MEMORY_FIELD_TYPE_FLOAT,
    MEMORY_FIELD_TYPE_INT,
    MEMORY_FIELD_TYPE_JSON,
    MEMORY_FIELD_TYPE_LIST,
    MEMORY_FIELD_TYPE_TEXT,
    MemoryField,
)
from rasa.mantle.memory.schema import ProjectMemorySchema
from rasa.mantle.skills.catalog import (
    SkillCatalog,
    is_prose_target_id,
    iter_resolved_activation_targets,
    load_default_skill_catalog_result,
    load_skill_catalog_result,
    ordered_block_ids_from_body,
    prose_segments_from_body,
)
from rasa.mantle.skills.skill import Skill
from rasa.mantle.tools.loader import TOOLS_DIR_NAME
from rasa.shared.constants import CONFIG_ADDITIONAL_LANGUAGES_KEY
from rasa.shared.project_structure import (
    MANTLE_INTEGRATIONS_FILE,
    MANTLE_MEMORY_FILE,
    MANTLE_REFERENCES_DIR,
)
from rasa.shared.utils.yaml import read_yaml_file

structlogger = structlog.get_logger()

_SKILLS_DIR = "skills"
_LIB_DIR = "lib"
_EXTERNAL_VECTOR_STORE_TYPES = frozenset({"qdrant", "milvus"})
_KNOWLEDGE_STORE_TYPES = frozenset({"faiss", "qdrant", "milvus"})
_UNKNOWN_ENUM_BUCKET = "other"
# Emit the spec's `num_execute_tool_steps` for the `execute` step kind.
_STEP_KIND_LABELS = {
    "autonomous": "autonomous",
    "collect": "collect",
    "action": "action",
    "execute": "execute_tool",
    "set_memory": "set_memory",
    "route": "route",
    "call": "call",
    "link": "link",
}
_MEMORY_TYPES = (
    MEMORY_FIELD_TYPE_TEXT,
    MEMORY_FIELD_TYPE_BOOL,
    MEMORY_FIELD_TYPE_INT,
    MEMORY_FIELD_TYPE_FLOAT,
    MEMORY_FIELD_TYPE_LIST,
    MEMORY_FIELD_TYPE_JSON,
    MEMORY_FIELD_TYPE_CATEGORICAL,
    MEMORY_FIELD_TYPE_ANY,
)


def build_mantle_training_started_attributes(
    project_root: Path,
    config_data: Optional[Mapping[str, Any]],
) -> dict[str, Any]:
    """Return the derived, non-sensitive ``Training Started`` attributes.

    Loads the skill catalog, memory schema, responses, and integrations from
    *project_root* and derives aggregate counts/enums. Never raises, and always
    returns the **full** key set: a section that fails leaves its keys at the
    defaults from :func:`_default_started_attributes`, so the Segment/warehouse
    schema stays stable across runs (no sparse/dynamic columns).

    Args:
        project_root: The Mantle project directory (parent of ``agent.yml``).
        config_data: The parsed ``agent.yml`` mapping, or ``None`` if unreadable.

    Returns:
        A flat mapping of telemetry property names to scalar values.
    """
    attributes = _default_started_attributes()
    agent_spec = _safe(lambda: agent_spec_from_config(config_data))
    catalog = _safe(lambda: _load_catalog(project_root))
    integrations = _safe(lambda: _read_integrations(project_root)) or {}

    _extend(attributes, lambda: _config_attributes(config_data))
    _extend(attributes, lambda: _agent_attributes(agent_spec))
    _extend(attributes, lambda: _scale_attributes(catalog))
    _extend(attributes, lambda: _authoring_attributes(catalog))
    _extend(attributes, lambda: _progressive_control_attributes(catalog))
    _extend(attributes, lambda: _memory_attributes(project_root, catalog))
    _extend(attributes, lambda: _filesystem_attributes(project_root))
    _extend(attributes, lambda: _integration_attributes(integrations, agent_spec))
    return attributes


def _default_started_attributes() -> dict[str, Any]:
    """Return every started-event property at its default (0 / False / None).

    Collectors override these; anything a failed section leaves untouched keeps
    its default, so the event always carries the same, complete key set.
    """
    defaults: dict[str, Any] = {
        "language": None,
        "num_additional_languages": 0,
        "num_skills": 0,
        "num_default_skills": 0,
        "num_custom_skills": 0,
        "num_disabled_skills": 0,
        "num_engine_managed_skills": 0,
        "num_steps": 0,
        "num_tools": 0,
        "num_shared_tools": 0,
        "num_project_responses": 0,
        "num_skill_responses": 0,
        "num_project_reference_files": 0,
        "num_skill_reference_files": 0,
        "num_before_end_hooks": 0,
        "num_autonomous_steps": 0,
        "num_collect_steps": 0,
        "num_action_steps": 0,
        "num_execute_tool_steps": 0,
        "num_set_memory_steps": 0,
        "num_route_steps": 0,
        "num_call_steps": 0,
        "num_link_steps": 0,
        "num_autonomous_skills": 0,
        "num_fully_guided_skills": 0,
        "num_hybrid_skills": 0,
        "max_ordered_blocks_in_skill": 0,
        "num_skills_with_precondition": 0,
        "num_hidden_skills": 0,
        "num_flows_with_complete_when": 0,
        "num_referenced_skills": 0,
        "num_referenced_blocks": 0,
        "num_tool_constraints": 0,
        "num_gated_tools": 0,
        "num_tools_requiring_confirmation": 0,
        "num_tools_with_on_success": 0,
        "num_tools_with_on_failure": 0,
        "num_scoped_instructions": 0,
        "num_project_memory_fields": 0,
        "num_skill_memory_fields": 0,
        "num_llm_settable_memory_fields": 0,
        "num_pii_memory_fields": 0,
        "llm_provider": None,
        "llm_model": None,
        "num_model_groups": 0,
        "embeddings_provider": None,
        "embeddings_model": None,
        "num_knowledge_stores": 0,
        "knowledge_store_types": json.dumps([]),
        "uses_external_vector_store": False,
        "num_mcp_servers": 0,
        "num_channels": 0,
        "channel_types": json.dumps([]),
        "has_voice_channel": False,
        "voice_asr_provider": None,
        "voice_tts_provider": None,
        "tracing_enabled": False,
        "tracing_type": None,
        "has_lib_dir": False,
        "has_custom_rules": False,
        "has_custom_text_rules": False,
        "has_custom_voice_rules": False,
        "has_custom_ack_rule": False,
        "has_custom_ack_reminder": False,
        "has_custom_references_instructions": False,
        "ack_enabled": None,
        "num_ack_examples": 0,
    }
    for name in _MEMORY_TYPES:
        defaults[f"num_memory_fields_by_type_{name}"] = 0
    return defaults


def _safe(builder: Callable[[], Any]) -> Any:
    """Run *builder*, returning its value or ``None`` if it raises."""
    try:
        return builder()
    except Exception as error:
        structlogger.debug("mantle.training_telemetry.load_failed", exc_info=error)
        return None


def _extend(attributes: dict[str, Any], builder: Callable[[], dict[str, Any]]) -> None:
    """Merge *builder*'s output into *attributes*, skipping it on failure."""
    try:
        attributes.update(builder())
    except Exception as error:
        structlogger.debug("mantle.training_telemetry.section_failed", exc_info=error)


def _load_catalog(project_root: Path) -> SkillCatalog:
    """Load the merged (defaults + project) catalog, tolerating per-skill errors."""
    defaults = load_default_skill_catalog_result().catalog
    return load_skill_catalog_result(Path(project_root), defaults=defaults).catalog


def _config_attributes(config_data: Optional[Mapping[str, Any]]) -> dict[str, Any]:
    additional = (
        config_data.get(CONFIG_ADDITIONAL_LANGUAGES_KEY)
        if isinstance(config_data, Mapping)
        else None
    )
    count = len(additional) if isinstance(additional, list) else 0
    return {"num_additional_languages": count}


def _agent_attributes(agent_spec: Optional[AgentSpec]) -> dict[str, Any]:
    if agent_spec is None:
        return {}
    fillers = agent_spec.fillers
    return {
        "language": agent_spec.language,
        "num_before_end_hooks": len(agent_spec.before_end),
        "num_ack_examples": len(fillers.examples),
        "ack_enabled": fillers.enabled,
        "has_custom_rules": bool(agent_spec.rules),
        "has_custom_text_rules": bool(agent_spec.orchestrator.text_rules),
        "has_custom_voice_rules": bool(agent_spec.orchestrator.voice_rules),
        "has_custom_ack_rule": bool(fillers.instructions),
        "has_custom_ack_reminder": bool(fillers.reminder),
        "has_custom_references_instructions": bool(
            agent_spec.knowledge_answering.instructions
        ),
    }


def _user_skills(catalog: SkillCatalog) -> list[Skill]:
    """Return author-written skills, excluding bundled engine defaults.

    Authoring/memory/progressive-control metrics describe what the builder made,
    so bundled default skills (identical across every project) are excluded from
    them. The overall skill census (:func:`_scale_attributes`) still counts all.
    """
    return [skill for skill in catalog.skills.values() if not skill.is_default]


def _scale_attributes(catalog: Optional[SkillCatalog]) -> dict[str, Any]:
    if catalog is None:
        return {}
    from rasa.mantle.tools.mcp_import_spec import try_parse_mcp_tool_import

    skills = list(catalog.skills.values())
    tool_names: set[str] = set()
    for skill in skills:
        # ``declared_tool_names`` intentionally omits MCP-only bare names so the
        # shared-tool loader does not allowlist them; telemetry still counts them.
        tool_names.update(catalog.declared_tool_names(skill.id))
        for import_reference in skill.import_tool_names:
            try:
                mcp_import = try_parse_mcp_tool_import(import_reference)
            except ValueError:
                continue
            if mcp_import is not None:
                tool_names.add(mcp_import.tool_name)
    return {
        "num_skills": len(skills),
        "num_default_skills": sum(1 for s in skills if s.is_default),
        "num_custom_skills": sum(1 for s in skills if not s.is_default),
        "num_disabled_skills": sum(1 for s in skills if s.disabled),
        "num_engine_managed_skills": sum(1 for s in skills if s.engine_managed),
        "num_tools": len(tool_names),
    }


def _authoring_attributes(catalog: Optional[SkillCatalog]) -> dict[str, Any]:
    if catalog is None:
        return {}
    skills = _user_skills(catalog)
    kinds = {
        "autonomous": 0,
        "collect": 0,
        "action": 0,
        "execute": 0,
        "set_memory": 0,
        "route": 0,
        "call": 0,
        "link": 0,
    }
    num_steps = 0
    for skill in skills:
        for target in iter_resolved_activation_targets(skill):
            in_ordered_block = not is_prose_target_id(skill.id, target.target_id)
            for step in target.steps:
                kind = getattr(step, "kind", None)
                if kind == "end":
                    continue
                num_steps += 1
                # An autonomous step in the synthetic prose view is the compiled
                # prose body, not an authored LLM step; count only those inside
                # ordered blocks.
                if kind == "autonomous" and not in_ordered_block:
                    continue
                if kind in kinds:
                    kinds[kind] += 1
    block_counts = [len(ordered_block_ids_from_body(skill)) for skill in skills]
    attributes = {
        f"num_{_STEP_KIND_LABELS[kind]}_steps": count for kind, count in kinds.items()
    }
    attributes.update(
        {
            "num_steps": num_steps,
            "max_ordered_blocks_in_skill": max(block_counts) if block_counts else 0,
            "num_skills_with_precondition": sum(
                1 for s in skills if s.precondition is not None
            ),
            "num_hidden_skills": sum(1 for s in skills if s.hidden),
            "num_flows_with_complete_when": sum(
                1
                for skill in skills
                for target in iter_resolved_activation_targets(skill)
                if target.complete_when is not None
            ),
            "num_referenced_skills": sum(len(s.referenced_skills) for s in skills),
            "num_referenced_blocks": sum(len(s.referenced_blocks) for s in skills),
            **_skill_type_counts(skills),
        }
    )
    return attributes


def _skill_type_counts(skills: list[Skill]) -> dict[str, int]:
    autonomous = fully_guided = hybrid = 0
    for skill in skills:
        has_prose = any(
            is_prose_target_id(skill.id, target.target_id)
            for target in iter_resolved_activation_targets(skill)
        )
        has_blocks = bool(ordered_block_ids_from_body(skill))
        if has_prose and has_blocks:
            hybrid += 1
        elif has_prose:
            autonomous += 1
        elif has_blocks:
            fully_guided += 1
    return {
        "num_autonomous_skills": autonomous,
        "num_fully_guided_skills": fully_guided,
        "num_hybrid_skills": hybrid,
    }


def _progressive_control_attributes(
    catalog: Optional[SkillCatalog],
) -> dict[str, Any]:
    if catalog is None:
        return {}
    gates: dict[tuple[str, str], Any] = {}
    scoped_instructions = 0
    for skill in _user_skills(catalog):
        scoped_instructions += sum(
            1
            for segment in prose_segments_from_body(skill)
            if segment.condition is not None
        )
        skill_gates = list(skill.tools) + [
            gate
            for target in iter_resolved_activation_targets(skill)
            for gate in target.tools
        ]
        for gate in skill_gates:
            gates.setdefault((skill.id, gate.name), gate)
    constrained = [
        gate
        for gate in gates.values()
        if gate.requires is not None
        or gate.requires_confirmation is not None
        or gate.on_success is not None
        or gate.on_failure is not None
    ]
    return {
        "num_tool_constraints": len(constrained),
        "num_gated_tools": sum(1 for g in gates.values() if g.requires is not None),
        "num_tools_requiring_confirmation": sum(
            1 for g in gates.values() if g.requires_confirmation is not None
        ),
        "num_tools_with_on_success": sum(
            1 for g in gates.values() if g.on_success is not None
        ),
        "num_tools_with_on_failure": sum(
            1 for g in gates.values() if g.on_failure is not None
        ),
        "num_scoped_instructions": scoped_instructions,
    }


def _memory_attributes(
    project_root: Path, catalog: Optional[SkillCatalog]
) -> dict[str, Any]:
    project_fields = _project_memory_fields(project_root)
    skill_fields: list[MemoryField] = []
    if catalog is not None:
        for skill in _user_skills(catalog):
            skill_fields.extend(skill.memory.definition.all_fields().values())
    all_fields = project_fields + skill_fields
    by_type = {f"num_memory_fields_by_type_{name}": 0 for name in _MEMORY_TYPES}
    for field in all_fields:
        key = f"num_memory_fields_by_type_{field.type}"
        if key in by_type:
            by_type[key] += 1
    return {
        "num_project_memory_fields": len(project_fields),
        "num_skill_memory_fields": len(skill_fields),
        "num_llm_settable_memory_fields": sum(1 for f in all_fields if f.llm_settable),
        "num_pii_memory_fields": sum(1 for f in all_fields if f.pii),
        **by_type,
    }


def _project_memory_fields(project_root: Path) -> list[MemoryField]:
    memory_file = Path(project_root) / MANTLE_MEMORY_FILE
    if not memory_file.is_file():
        return []
    return list(ProjectMemorySchema.from_yaml(memory_file).fields.values())


def _filesystem_attributes(project_root: Path) -> dict[str, Any]:
    root = Path(project_root)
    skills_dir = root / _SKILLS_DIR
    skill_dirs = (
        [d for d in skills_dir.iterdir() if d.is_dir()] if skills_dir.is_dir() else []
    )
    return {
        "num_shared_tools": _count_tool_modules(root / TOOLS_DIR_NAME),
        "num_project_responses": _count_responses(root / RESPONSES_FILENAME),
        "num_skill_responses": sum(
            _count_responses(d / RESPONSES_FILENAME) for d in skill_dirs
        ),
        "num_project_reference_files": _count_files(root / MANTLE_REFERENCES_DIR),
        "num_skill_reference_files": sum(
            _count_files(d / MANTLE_REFERENCES_DIR) for d in skill_dirs
        ),
        "has_lib_dir": (root / _LIB_DIR).is_dir(),
    }


def _count_tool_modules(tools_dir: Path) -> int:
    if not tools_dir.is_dir():
        return 0
    return sum(
        1
        for path in tools_dir.rglob("*.py")
        if path.is_file() and path.name != "__init__.py"
    )


def _count_files(directory: Path) -> int:
    if not directory.is_dir():
        return 0
    return sum(1 for path in directory.rglob("*") if path.is_file())


def _count_responses(responses_file: Path) -> int:
    if not responses_file.is_file():
        return 0
    return len(ResponseRegistry.from_yaml(responses_file).responses)


def _read_integrations(project_root: Path) -> Mapping[str, Any]:
    path = Path(project_root) / MANTLE_INTEGRATIONS_FILE
    if not path.is_file():
        return {}
    raw = read_yaml_file(path, expand_env_vars=False)
    return raw if isinstance(raw, Mapping) else {}


def _integration_attributes(
    integrations: Mapping[str, Any], agent_spec: Optional[AgentSpec]
) -> dict[str, Any]:
    model_groups = integrations.get("model_groups") or []
    attributes: dict[str, Any] = {}
    attributes.update(_llm_attributes(model_groups, agent_spec))
    attributes.update(_embeddings_attributes(model_groups, agent_spec))
    attributes.update(_knowledge_store_attributes(integrations))
    attributes.update(_channel_attributes(integrations))
    attributes["num_model_groups"] = (
        len(model_groups) if isinstance(model_groups, list) else 0
    )
    attributes["num_mcp_servers"] = len(integrations.get("mcp_servers") or {})
    tracing = integrations.get("tracing")
    attributes["tracing_enabled"] = bool(tracing)
    attributes["tracing_type"] = (
        tracing.get("type") if isinstance(tracing, Mapping) else None
    )
    return attributes


def _llm_attributes(
    model_groups: Any, agent_spec: Optional[AgentSpec]
) -> dict[str, Any]:
    """Return orchestrator provider and model from the named model group.

    ``agent.yml`` ``orchestrator.model_group`` selects the group. Only the model
    *name* is collected; an Azure ``deployment`` is a customer resource identifier
    the sensitivity policy forbids, so it is never sent (``llm_provider`` already
    signals Azure).
    """
    group_id = agent_spec.orchestrator.model_group if agent_spec is not None else ""
    provider, model = (
        _model_group_pair(model_groups, group_id) if group_id else (None, None)
    )
    return {"llm_provider": provider, "llm_model": model}


def _model_group_pair(
    model_groups: Any, group_id: str
) -> tuple[Optional[str], Optional[str]]:
    if not isinstance(model_groups, list):
        return None, None
    for group in model_groups:
        if isinstance(group, Mapping) and group.get("id") == group_id:
            models = group.get("models") or []
            if models and isinstance(models[0], Mapping):
                # Deliberately not falling back to ``deployment`` — it is a
                # customer resource identifier excluded by the sensitivity policy.
                return models[0].get("provider"), models[0].get("model")
    return None, None


def _embeddings_attributes(
    model_groups: Any, agent_spec: Optional[AgentSpec]
) -> dict[str, Any]:
    group_id = (
        agent_spec.knowledge_answering.embeddings if agent_spec is not None else ""
    )
    provider, model = (
        _model_group_pair(model_groups, group_id) if group_id else (None, None)
    )
    return {"embeddings_provider": provider, "embeddings_model": model}


def _knowledge_store_attributes(integrations: Mapping[str, Any]) -> dict[str, Any]:
    stores = integrations.get("knowledge_stores") or []
    if not isinstance(stores, list):
        stores = []
    raw_types = [
        str(store["type"])
        for store in stores
        if isinstance(store, Mapping) and isinstance(store.get("type"), str)
    ]
    # Allowlist to the known vector-store backends; a custom ``type`` is an
    # author-chosen identifier, so it is bucketed as "other" rather than emitted.
    types = sorted({_allowlisted(t, _KNOWLEDGE_STORE_TYPES) for t in raw_types})
    return {
        "num_knowledge_stores": len(stores),
        "knowledge_store_types": json.dumps(types),
        "uses_external_vector_store": any(
            t in _EXTERNAL_VECTOR_STORE_TYPES for t in raw_types
        ),
    }


def _allowlisted(value: str, allowlist: frozenset[str]) -> str:
    """Return *value* if in *allowlist*, else the ``"other"`` bucket."""
    return value if value in allowlist else _UNKNOWN_ENUM_BUCKET


def _channel_attributes(integrations: Mapping[str, Any]) -> dict[str, Any]:
    from rasa.core.channels import BUILTIN_CHANNELS

    builtin_channels = frozenset(BUILTIN_CHANNELS)
    channels = integrations.get("channels") or {}
    if not isinstance(channels, Mapping):
        channels = {}
    enabled = [name for name, cfg in channels.items() if _channel_enabled(cfg)]
    has_voice, asr_provider, tts_provider = _voice_channel_providers(channels, enabled)
    # Allowlist channel names to the built-in registry; a custom channel key is
    # an author-chosen identifier, so it is bucketed as "other".
    channel_types = sorted({_allowlisted(name, builtin_channels) for name in enabled})
    return {
        "num_channels": len(enabled),
        "channel_types": json.dumps(channel_types),
        "has_voice_channel": has_voice,
        "voice_asr_provider": asr_provider,
        "voice_tts_provider": tts_provider,
    }


def _channel_enabled(cfg: Any) -> bool:
    if cfg is None:
        return True
    if isinstance(cfg, Mapping):
        return cfg.get("enabled", True) is not False
    return True


def _voice_channel_providers(
    channels: Mapping[str, Any], enabled: list[str]
) -> tuple[bool, Optional[str], Optional[str]]:
    for name in enabled:
        cfg = channels.get(name)
        if not isinstance(cfg, Mapping) or ("asr" not in cfg and "tts" not in cfg):
            continue
        asr = cfg.get("asr")
        tts = cfg.get("tts")
        return (
            True,
            asr.get("provider") if isinstance(asr, Mapping) else None,
            tts.get("provider") if isinstance(tts, Mapping) else None,
        )
    return False, None, None
